const state={
  sessionFilter:'active',
  selectedSession:'research',
  selectedNode:'atlas',
  selectedTool:'cordis',
  selectedSetting:'models',
  completed:false,
  settings:{
    models:{state:'connected',provider:'minimax',protocol:'responses',defaultModel:'MiniMax-M3',authSource:'hosted',applyAt:'2m ago'},
    agentRuntime:{state:'ready',agents:3,active:'Atlas',queues:1,applyAt:'5m ago'},
    connectivity:{state:'healthy',discovery:'local-relay',channels:['user-input','local-worker-01'],tailscale:'off',applyAt:'12m ago'},
    observability:{state:'on',logTtlDays:14,sessionLogPath:'~/.freehand/session-log',snapshot:'idle',applyAt:'30m ago'},
    appearance:{state:'applied',theme:'system-light',density:'comfortable',locale:'zh-CN',applyAt:'1h ago'},
    about:{state:'ok',runtime:'freehand v2 prototype',node:'local-freehand',build:'mock-static'}
  },
  timers:[
    {id:'t1',mode:'relative',label:'Research brief check-in',delay:'15m',repeat:'once',status:'armed',next:'in 14m',source:'research',reason:'auto wake',wake:'Summarize latest evidence',maxRuns:1,history:[{t:'created',at:'12m ago'}]},
    {id:'t2',mode:'cron',label:'Daily standup prep',delay:'-',repeat:'weekday 08:30',status:'paused',next:'tomorrow 08:30',source:'deploy',reason:'team reminder',wake:'Prepare daily brief',maxRuns:60,history:[{t:'paused',at:'1h ago'}]}
  ],
  timerDraft:{mode:'relative',delay:'10m',runAt:'',repeat:'once',interval:'',timeOfDay:'',weekdays:'',cron:'',maxRuns:'1',sourceSession:'research',reason:'',wakePrompt:''},
  tools:[
    {id:'cordis',name:'Cordis design',kind:'plugin',status:'active',scope:'composition',schema:'cordis.plugin:v1',exposure:'in-app',permission:'none',example:'register(plugin, ctx => ...)'},
    {id:'session-log',name:'Session Log',kind:'plugin',status:'active',scope:'reasoning',schema:'sessionlog.event:v1',exposure:'local+remote',permission:'fs:read',example:'append({kind, status, fact})'},
    {id:'memory',name:'Memory plugin',kind:'plugin',status:'attached',scope:'session',schema:'memory.record:v1',exposure:'local',permission:'fs:write',example:'summarize(sessionId)'},
    {id:'search',name:'Search plugin',kind:'plugin',status:'ready',scope:'runtime',schema:'search.index:v1',exposure:'local',permission:'net:out',example:'search("meeting notes")'},
    {id:'canvas',name:'SessionCanvas',kind:'plugin',status:'ready',scope:'ui',schema:'canvas.node:v1',exposure:'in-app',permission:'none',example:'focus(sessionId)'},
    {id:'ui-adaptor',name:'UiAdaptor',kind:'adaptor',status:'connected',scope:'ui',schema:'adp.command:v1',exposure:'in-app',permission:'none',example:'sendPrompt(sessionId, text)'},
    {id:'timer',name:'Timer dashboard',kind:'plugin',status:'ready',scope:'scheduler',schema:'timer.task:v1',exposure:'local+remote',permission:'scheduler:write',example:'schedule({mode:"cron", cron:"0 8 * * 1-5"})'}
  ],
  notifications:[
    {id:'n1',priority:'high',title:'Approval required',text:'Atlas is waiting for confirmation before publishing the brief.',time:'2m ago',read:false,action:'Review'},
    {id:'n2',priority:'medium',title:'Worker connected',text:'Nova joined through Channel · local-worker-01.',time:'8m ago',read:false,action:'Open topology'},
    {id:'n3',priority:'medium',title:'Memory saved',text:'Session summary updated from the last closed turn.',time:'18m ago',read:false,action:'Open memory'}
  ],
  sessions:[
    {id:'research',title:'Research brief',meta:'Atlas · just now',status:'running',band:'active'},
    {id:'deploy',title:'Release checklist',meta:'Nova · 12m ago',status:'waiting',band:'active'},
    {id:'meeting',title:'Meeting notes',meta:'Atlas · yesterday',status:'complete',band:'recent'},
    {id:'migration',title:'Migration review',meta:'Orion · Aug 28',status:'complete',band:'history'}
  ]
};

const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let toastTimer;
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2200)}

function renderTopology(){const nodes=[['machine','⌂','Mac Studio','online',''],['node','◈','local-freehand','ready','indent-1'],['agent','●','Atlas','reasoning','indent-2'],['channel','↔','user-input','open','indent-2'],['agent','●','Nova','waiting','indent-2'],['channel','↔','local-worker-01','open','indent-2']];$('#topology-tree').innerHTML='<div class="tree-group">'+nodes.map(([type,icon,label,meta,indent])=>`<button class="tree-row ${indent} ${label.toLowerCase()===state.selectedNode?'selected':''}" data-node="${label}"><span class="tree-icon">${icon}</span><span class="tree-label">${label}</span><span class="tree-meta">${meta}</span></button>`).join('')+'</div>'}

function renderSessions(){const bands={active:'Active',recent:'Recent',history:'History'};const rows=state.sessions.filter(x=>x.band===state.sessionFilter);$('#session-list').innerHTML=rows.length?rows.map(x=>`<div class="session-item ${x.id===state.selectedSession?'selected':''}" data-session="${x.id}"><strong>${x.title}</strong><small>${x.meta}</small><span class="session-status"><span class="status-dot ${x.status==='complete'?'blue':''}"></span>${x.status}</span></div>`).join(''):`<p class="muted">No ${bands[state.sessionFilter].toLowerCase()} sessions.</p>`;$$('[data-session-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.sessionFilter===state.sessionFilter);b.setAttribute('aria-selected',b.dataset.sessionFilter===state.sessionFilter)});$('#active-count').textContent=state.sessions.filter(x=>x.band==='active').length}

function renderNotifications(){const weight=p=>p==='high'?0:p==='medium'?1:2;const list=[...state.notifications].sort((a,b)=>weight(a.priority)-weight(b.priority)||a.id.localeCompare(b.id));$('#notifications').innerHTML=list.map(n=>`<article class="notification-item ${n.priority} ${n.read?'read':''}" data-notification="${n.id}"><div class="notification-head"><strong>${n.title}</strong><span class="priority ${n.priority}">${n.priority==='high'?'HIGH':'MEDIUM'}</span></div><p>${n.text}</p><div class="notification-foot"><span>${n.time}</span><button data-notification-action="${n.id}">${n.read?'Acknowledged':n.action}</button></div></article>`).join('');const unread=state.notifications.filter(n=>!n.read).length;$('#attention-count').textContent=unread;$('#mobile-attention-count').textContent=unread}

function renderPlugins(){const items=[['C','Cordis design','composition active','green','Active'],['R','Reasoning backend','Freehand native','blue',state.completed?'Complete':'Running'],['M','Memory plugin','attached · auto-save','purple','Attached'],['S','Search plugin','index healthy','blue','Ready'],['T','Timer dashboard','scheduler ready','blue','Ready']];$('#plugin-list').innerHTML=items.map(x=>`<div class="plugin-row"><span class="plugin-icon ${x[3]}">${x[0]}</span><div><strong>${x[1]}</strong><small>${x[2]}</small></div><span class="plugin-state">${x[4]}</span></div>`).join('')}

function renderTimeline(){const rows=[['◎','You','User input','Find the strongest signals from the last three research sessions.','just now'],['◌','Atlas','Reasoning','Comparing Session Log records and checking source relevance.','working'],['↗','Search plugin','Capability invocation','Indexed 24 records · 6 high-confidence matches.','12s ago'],['✓','Atlas','Result','Drafting a concise brief with cited session sources.','now']];$('#timeline').innerHTML=rows.map((r,i)=>`<div class="timeline-row ${i===1&&!state.completed?'active':''}"><div class="timeline-marker">${r[0]}</div><div class="timeline-card"><header><div><strong>${r[1]}</strong><small> · ${r[2]}</small></div><small>${r[4]}</small></header><p>${r[3]}</p>${i===2?'<div class="timeline-detail">Source scope: 24 session records · cache hit 82% · cursor s:24:018</div>':''}</div></div>`).join('')}

function render(){renderTopology();renderSessions();renderNotifications();renderPlugins();renderTimeline();const run=$('#run-status');run.className='run-status '+(state.completed?'completed':'running');run.innerHTML=state.completed?'<span class="status-dot blue"></span><strong>Completed</strong><span>Terminal projection is stable and ready for review</span><button class="text-button" data-action="simulate-running">Simulate running</button>':'<span class="status-dot"></span><strong>Running</strong><span>Reasoning backend is processing the current turn</span><button class="text-button" data-action="simulate-complete">Simulate complete</button>'}

function modal(title,body){$('#modal-root').innerHTML=`<div class="modal-backdrop" data-close-modal><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header><div><span class="eyebrow">Cordis surface</span><h2 id="modal-title">${title}</h2></div><button class="icon-button" data-action="close-modal" aria-label="关闭">×</button></header><div class="modal-body">${body}</div></section></div>`}

function openSearch(){modal('Global Search',`<form class="search-form" id="search-form"><label class="sr-only" for="search-input">搜索关键词</label><input id="search-input" placeholder="Search sessions, Agents, memory..." autofocus><button class="primary-button">Search</button></form><div id="search-results"><p class="muted">Search Plugin ready · index healthy · 24 records</p></div>`);$('#search-form').addEventListener('submit',e=>{e.preventDefault();const q=$('#search-input').value.trim()||'research';const hits=state.sessions.filter(s=>s.title.toLowerCase().includes(q.toLowerCase())||s.meta.toLowerCase().includes(q.toLowerCase()));$('#search-results').innerHTML=(hits.length?hits.map(s=>`<div class="search-result"><strong>${s.title}</strong><small>session · ${s.meta} · source: SessionCanvasPlugin</small></div>`).join(''):`<p class="muted">No plugin results for “${q}”. Index remains healthy.</p>`);toast('SearchPlugin returned classified results')})}

function openMemory(){modal('Session Memory',`<div class="memory-state"><strong>Attached · automatic trigger enabled</strong><br><small>Source: Research brief · provenance: Session Log · last save 18m ago</small></div><div class="memory-actions"><button class="primary-button" data-memory="summarize">Summarize</button><button class="ghost-button" data-memory="save">Save record</button><button class="ghost-button" data-memory="load">Load memory</button><button class="ghost-button" data-memory="export">Export</button><button class="ghost-button" data-memory="detach">Detach</button></div><p id="memory-result" class="muted">Memory Plugin is ready for session-scoped operations.</p>`)}

function openCanvas(){modal('Sessions / Canvas',`<p class="muted">SessionCanvasPlugin projection · active / recent / history</p><div class="canvas"><span class="canvas-line" style="left:135px;top:105px;width:190px;transform:rotate(16deg)"></span><span class="canvas-line" style="left:245px;top:205px;width:130px;transform:rotate(-32deg)"></span><div class="canvas-node active" style="left:26px;top:70px">Research brief<br><small>active · Atlas</small></div><div class="canvas-node" style="left:290px;top:115px">Release checklist<br><small>active · Nova</small></div><div class="canvas-node" style="left:180px;top:220px">Meeting notes<br><small>recent</small></div></div><p class="muted">Select a node to focus the Run surface. Edges are derived from Session Log relationships.</p>`)}

function openDetails(){const s=state.sessions.find(x=>x.id===state.selectedSession);modal('Session details',`<div class="detail-row"><strong>Session</strong><span>${s.title}</span></div><div class="detail-row"><strong>Agent</strong><span>Atlas</span></div><div class="detail-row"><strong>Backend</strong><span>Freehand native</span></div><div class="detail-row"><strong>Memory</strong><span>Attached · auto-save</span></div><div class="detail-row"><strong>Source</strong><span>Session Log projection</span></div>`)}

function openSettings(){const groups=[{id:'models',label:'Models',desc:'Provider adapter · model groups · auth source'},{id:'agentRuntime',label:'Agent runtime',desc:'Active Agents · queues · resource budget'},{id:'connectivity',label:'Connectivity',desc:'Channel discovery · relay · tailscale'},{id:'observability',label:'Observability',desc:'Session Log · snapshot · retention'},{id:'appearance',label:'Appearance',desc:'Theme · density · locale'},{id:'about',label:'About',desc:'Runtime identity · build · node'}];const renderDetail=()=>{const id=state.selectedSetting;const cfg=state.settings[id];const fields={models:[{k:'Provider',v:cfg.provider},{k:'Protocol',v:cfg.protocol},{k:'Default model',v:cfg.defaultModel},{k:'Auth source',v:cfg.authSource},{k:'Last apply',v:cfg.applyAt}],agentRuntime:[{k:'State',v:cfg.state},{k:'Agents',v:cfg.agents},{k:'Active',v:cfg.active},{k:'Queues',v:cfg.queues},{k:'Last apply',v:cfg.applyAt}],connectivity:[{k:'State',v:cfg.state},{k:'Discovery',v:cfg.discovery},{k:'Channels',v:(cfg.channels||[]).join(', ')||'—'},{k:'Tailscale',v:cfg.tailscale},{k:'Last apply',v:cfg.applyAt}],observability:[{k:'State',v:cfg.state},{k:'Log TTL (days)',v:cfg.logTtlDays},{k:'Session Log path',v:cfg.sessionLogPath},{k:'Snapshot',v:cfg.snapshot},{k:'Last apply',v:cfg.applyAt}],appearance:[{k:'Theme',v:cfg.theme},{k:'Density',v:cfg.density},{k:'Locale',v:cfg.locale},{k:'Last apply',v:cfg.applyAt}],about:[{k:'Runtime',v:cfg.runtime},{k:'Node',v:cfg.node},{k:'Build',v:cfg.build}]}[id]||[];return `<div class="settings-detail"><header><strong>${groups.find(g=>g.id===id).label}</strong><small>${groups.find(g=>g.id===id).desc}</small><span class="status-dot online"></span><span>${cfg.state}</span></header><div class="settings-fields">${fields.map(f=>`<div class="detail-row"><strong>${f.k}</strong><span>${f.v}</span></div>`).join('')}</div><div class="memory-actions"><button class="primary-button" data-settings-action="apply" data-settings-key="${id}">Apply</button><button class="ghost-button" data-settings-action="reset" data-settings-key="${id}">Reset</button></div><p id="settings-feedback" class="muted">Settings group ready · review-only mock projection.</p></div>`};modal('Settings',`<div class="settings-shell"><nav class="settings-nav" aria-label="Settings groups">${groups.map(g=>`<button class="settings-tab ${g.id===state.selectedSetting?'active':''}" data-settings-group="${g.id}">${g.label}</button>`).join('')}</nav><div id="settings-detail" class="settings-detail-host">${renderDetail()}</div></div>`);$$('[data-settings-group]').forEach(b=>b.addEventListener('click',()=>{state.selectedSetting=b.dataset.settingsGroup;openSettings()}))}

function openTimer(){const draft=state.timerDraft;const repeatField=draft.mode==='cron'?`<label>Weekdays<input id="t-weekdays" value="${draft.weekdays}" placeholder="1-5"></label><label>Cron<input id="t-cron" value="${draft.cron}" placeholder="0 8 * * 1-5"></label>`:draft.mode==='interval'?`<label>Interval<input id="t-interval" value="${draft.interval}" placeholder="30m"></label>`:draft.mode==='daily'?`<label>Time of day<input id="t-tod" value="${draft.timeOfDay}" placeholder="08:30"></label>`:draft.mode==='weekly'?`<label>Weekdays<input id="t-weekdays" value="${draft.weekdays}" placeholder="Mon, Wed"></label>`:'';const list=state.timers.map(t=>`<article class="timer-row ${t.status}" data-timer="${t.id}"><div><strong>${t.label}</strong><small>${t.mode} · ${t.repeat||t.delay||'—'} · source: ${t.source}</small><small>next: ${t.next} · maxRuns: ${t.maxRuns}</small></div><span class="timer-state ${t.status}">${t.status}</span><div class="timer-actions"><button class="ghost-button" data-timer-action="toggle" data-timer-id="${t.id}">${t.status==='paused'?'Resume':'Pause'}</button><button class="ghost-button" data-timer-action="cancel" data-timer-id="${t.id}">Cancel</button></div></article>`).join('');const history=state.timers.flatMap(t=>t.history.map(h=>({t:h.at,label:`${t.label} · ${h.t}`}))).slice(-6).map(h=>`<div class="timer-history-row"><small>${h.t}</small><span>${h.label}</span></div>`).join('');modal('Timer dashboard',`<div class="timer-shell"><form id="timer-form" class="timer-form"><header><strong>Create timer</strong><small>Scheduler plugin · Session Log reconciled</small></header><div class="timer-grid"><label>Mode<select id="t-mode">${['relative','absolute','interval','daily','weekly','cron'].map(m=>`<option value="${m}" ${m===draft.mode?'selected':''}>${m}</option>`).join('')}</select></label>${draft.mode==='relative'?`<label>Delay<input id="t-delay" value="${draft.delay}" placeholder="15m"></label>`:''}${draft.mode==='absolute'?`<label>Run at<input id="t-runat" value="${draft.runAt}" placeholder="2026-09-01T09:00"></label>`:''}${repeatField}<label>Max runs<input id="t-maxruns" value="${draft.maxRuns}"></label><label>Source session<select id="t-source">${state.sessions.map(s=>`<option value="${s.id}" ${s.id===draft.sourceSession?'selected':''}>${s.title}</option>`).join('')}</select></label><label>Reason<input id="t-reason" value="${draft.reason}" placeholder="auto wake"></label><label class="timer-grid-wide">Wake prompt<input id="t-wake" value="${draft.wakePrompt}" placeholder="Summarize latest evidence"></label></div><div class="memory-actions"><button class="primary-button" type="submit">Create timer</button><button class="ghost-button" type="button" data-action="refresh-timers">Refresh timers</button></div><p id="timer-status" class="muted">Timer plugin ready · scheduler idle</p></form><section class="timer-list-section"><header><strong>Active timers</strong><small>${state.timers.length} tracked · Session Log ledger synced</small></header><div id="timer-list">${list||'<p class="muted">No timers yet · create one to populate.</p>'}</div></section><section class="timer-list-section"><header><strong>History</strong><small>Recent scheduler events</small></header><div id="timer-history">${history||'<p class="muted">No ledger events yet.</p>'}</div></section></div>`);$('#t-mode').addEventListener('change',e=>{state.timerDraft.mode=e.target.value;openTimer()});$('#timer-form').addEventListener('submit',e=>{e.preventDefault();const id='t'+(state.timers.length+1)+'-'+Date.now().toString(36);const mode=state.timerDraft.mode;const label=($('#t-reason').value||'Timer')+' · '+mode;const timer={id,mode,label,delay:$('#t-delay')&&$('#t-delay').value||($('#t-runat')&&$('#t-runat').value)||'-',repeat:mode==='cron'?($('#t-cron')&&$('#t-cron').value||'cron'):mode==='interval'?($('#t-interval')&&$('#t-interval').value||'interval'):mode==='daily'?($('#t-tod')&&$('#t-tod').value||'daily'):mode==='weekly'?($('#t-weekdays')&&$('#t-weekdays').value||'weekly'):'once',status:'armed',next:'in '+($('#t-delay')&&$('#t-delay').value||'15m'),source:$('#t-source').value,reason:$('#t-reason').value||'manual',wake:$('#t-wake').value||'',maxRuns:parseInt($('#t-maxruns').value||'1',10),history:[{t:'created',at:'just now'}]};state.timers.unshift(timer);state.timerDraft={mode,delay:$('#t-delay')&&$('#t-delay').value||state.timerDraft.delay,runAt:$('#t-runat')&&$('#t-runat').value||'',repeat:timer.repeat,interval:state.timerDraft.interval,timeOfDay:state.timerDraft.timeOfDay,weekdays:state.timerDraft.weekdays,cron:state.timerDraft.cron,maxRuns:$('#t-maxruns').value||'1',sourceSession:$('#t-source').value,reason:timer.reason,wakePrompt:timer.wake};$('#timer-status').textContent=`Timer ${timer.id} armed · scheduler entry created`;toast(`TimerPlugin: scheduled ${timer.label}`);openTimer()});$('[data-action="refresh-timers"]').addEventListener('click',()=>{$('#timer-status').textContent=`Refreshed · ${state.timers.length} timers synced from scheduler ledger`;toast('TimerPlugin: scheduler reconciled')})}

function openTools(){const t=state.tools.find(x=>x.id===state.selectedTool)||state.tools[0];const list=state.tools.map(x=>`<button class="tools-row ${x.id===state.selectedTool?'active':''}" data-tool="${x.id}"><div><strong>${x.name}</strong><small>${x.kind} · ${x.scope}</small></div><span class="tools-state ${x.status}">${x.status}</span></button>`).join('');modal('Tools registry',`<div class="tools-shell"><nav class="tools-nav" aria-label="Tools">${list}</nav><section class="tools-detail"><header><strong>${t.name}</strong><small>${t.kind} · schema ${t.schema}</small><span class="status-dot ${t.status==='active'?'online':''}"></span><span>${t.status}</span></header><div class="detail-row"><strong>Scope</strong><span>${t.scope}</span></div><div class="detail-row"><strong>Schema</strong><span>${t.schema}</span></div><div class="detail-row"><strong>Exposure</strong><span>${t.exposure}</span></div><div class="detail-row"><strong>Permission</strong><span>${t.permission}</span></div><div class="detail-row"><strong>Example</strong><span><code>${t.example}</code></span></div><div class="memory-actions"><button class="primary-button" data-tool-action="invoke">Invoke</button><button class="ghost-button" data-tool-action="detach">Detach</button></div><p id="tools-feedback" class="muted">Tools plugin projection · Cordis-driven registration</p></section></div>`);$$('[data-tool]').forEach(b=>b.addEventListener('click',()=>{state.selectedTool=b.dataset.tool;openTools()}))}

function openMobileSheet(view){const sheets={location:['Topology · mobile','LocationPlugin projection. Tap an Agent to focus it and return to Run.'],attention:['Attention · mobile','NotificationPlugin ranking by importance and time. Use Mark all read on desktop for the full flow.'],sessions:['Sessions · mobile','SessionCanvasPlugin projection. Choose a session to focus the Run surface.']};if(view==='more'){modal('More',`<div class="more-shell"><section class="more-group"><h3>操作</h3><button class="more-entry" data-mobile-entry="new-session"><span>＋</span><span><strong>新会话</strong><small>创建一个新的工作上下文</small></span></button><button class="more-entry" data-mobile-entry="timer"><span>⏱</span><span><strong>定时任务</strong><small>查看和管理唤醒计划</small></span></button></section><section class="more-group"><h3>信息</h3><button class="more-entry" data-mobile-entry="search"><span>⌕</span><span><strong>搜索</strong><small>查询会话、Agent 和记忆</small></span></button><button class="more-entry" data-mobile-entry="memory"><span>M</span><span><strong>记忆</strong><small>总结、加载和导出当前会话记忆</small></span></button></section><section class="more-group"><h3>系统</h3><button class="more-entry" data-mobile-entry="settings"><span>⚙</span><span><strong>配置</strong><small>模型、连接、运行时和可观测性</small></span></button><button class="more-entry" data-mobile-entry="tools"><span>⛭</span><span><strong>内置工具</strong><small>查看 Cordis 工具注册表</small></span></button></section></div>`);return}modal(sheets[view][0],`<p class="muted">${sheets[view][1]}</p><div class="memory-actions"><button class="primary-button" data-action="close-modal">Back to Run</button></div>`)}

function openMobileEntry(entry){const map={search:openSearch,settings:openSettings,timer:openTimer,tools:openTools,memory:openMemory};if(map[entry])map[entry]();else if(entry==='new-session'){state.selectedSession='research';$('#run-title').textContent='Research brief';$('#header-session').textContent='Research brief';renderSessions();$('#modal-root').innerHTML='';toast('New session command accepted by UiAdaptor')}}

document.addEventListener('click',e=>{
  const el=e.target.closest('[data-action]');
  const action=el&&el.dataset.action;
  if(action==='search')openSearch();
  if(action==='open-memory')openMemory();
  if(action==='open-canvas')openCanvas();
  if(action==='open-details')openDetails();
  if(action==='settings')openSettings();
  if(action==='open-timer')openTimer();
  if(action==='open-tools')openTools();
  if(action==='close-modal')$('#modal-root').innerHTML='';
  if(action==='new-session'){state.selectedSession='research';toast('New session command accepted by UiAdaptor')}
  if(action==='mark-all-read'){state.notifications.forEach(n=>n.read=true);render();toast('Notification projection acknowledged')}
  if(action==='simulate-complete'){state.completed=true;render();toast('Reasoning terminal projection received')}
  if(action==='simulate-running'){state.completed=false;render();toast('Reasoning resumed from Session Log boundary')}
  if(action==='refresh-topology'){renderTopology();toast('TopologyPlugin reconciled registry generation')}
  if(action==='refresh-timers'){$('#timer-status').textContent=`Refreshed · ${state.timers.length} timers synced from scheduler ledger`;toast('TimerPlugin: scheduler reconciled')}
  const settingsApply=e.target.closest('[data-settings-action]');
  if(settingsApply){const key=settingsApply.dataset.settingsKey;const op=settingsApply.dataset.settingsAction;if(op==='apply'){$('#settings-feedback').textContent=`Applied ${key} settings · Session Log recorded`;toast(`SettingsPlugin: applied ${key}`)}else{$('#settings-feedback').textContent=`Reset ${key} to plugin defaults`;toast(`SettingsPlugin: reset ${key}`)}}
  const timerBtn=e.target.closest('[data-timer-action]');
  if(timerBtn){const id=timerBtn.dataset.timerId;const op=timerBtn.dataset.timerAction;const t=state.timers.find(x=>x.id===id);if(t){if(op==='toggle'){t.status=t.status==='paused'?'armed':'paused';t.history.push({t:t.status==='armed'?'resumed':'paused',at:'just now'});toast(`TimerPlugin: ${t.status} ${t.label}`)}else if(op==='cancel'){t.status='cancelled';t.history.push({t:'cancelled',at:'just now'});toast(`TimerPlugin: cancelled ${t.label}`)}openTimer()}}
  const toolBtn=e.target.closest('[data-tool-action]');
  if(toolBtn){const op=toolBtn.dataset.toolAction;const t=state.tools.find(x=>x.id===state.selectedTool);if(op==='invoke'){$('#tools-feedback').textContent=`Invoked ${t.name} · typed command routed through UiAdaptor`;toast(`ToolsPlugin: invoked ${t.name}`)}else{$('#tools-feedback').textContent=`Detached ${t.name} · registry projection updated`;toast(`ToolsPlugin: detached ${t.name}`)}}
  const node=e.target.closest('[data-node]');
  if(node){state.selectedNode=node.dataset.node.toLowerCase();renderTopology();toast(`Focused topology node: ${node.dataset.node}`)}
  const filter=e.target.closest('[data-session-filter]');
  if(filter){state.sessionFilter=filter.dataset.sessionFilter;renderSessions()}
  const sess=e.target.closest('[data-session]');
  if(sess){state.selectedSession=sess.dataset.session;const s=state.sessions.find(x=>x.id===state.selectedSession);$('#run-title').textContent=s.title;$('#header-session').textContent=s.title;renderSessions();toast(`SessionCanvas focused: ${s.title}`)}
  const not=e.target.closest('[data-notification-action]');
  if(not){const n=state.notifications.find(x=>x.id===not.dataset.notificationAction);if(n.title==='Open topology'){state.selectedNode='nova';renderTopology();toast('Topology detail opened from notification')}else if(n.title==='Open memory'){openMemory()}else{n.read=true;renderNotifications();toast('Notification acknowledged')}}
  const mem=e.target.closest('[data-memory]');
  if(mem){const op=mem.dataset.memory;const messages={summarize:'Summary generated from Session Log; original transcript unchanged.',save:'Memory record saved with session provenance.',load:'Memory loaded into plugin context; transcript unchanged.',export:'Export reference created by Memory Plugin.',detach:'Memory Plugin detached from this session.'};$('#memory-result').textContent=messages[op];toast(`MemoryPlugin: ${op}`)}
  const back=e.target.closest('[data-close-modal]');
  if(back&&e.target===back)$('#modal-root').innerHTML='';
  const mobile=e.target.closest('[data-mobile-view]');
  if(mobile){$$('.mobile-nav-item').forEach(b=>b.classList.toggle('active',b===mobile));if(mobile.dataset.mobileView!=='run')openMobileSheet(mobile.dataset.mobileView);else toast('Run surface focused')}
  const mobileEntry=e.target.closest('[data-mobile-entry]');
  if(mobileEntry){openMobileEntry(mobileEntry.dataset.mobileEntry)}
});

document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#modal-root').innerHTML=''});

$('#composer').addEventListener('submit',e=>{e.preventDefault();const input=$('#prompt');if(!input.value.trim())return;$('#receipt').textContent='Accepted · typed command routed to design plugin';toast('UiAdaptor accepted the command');input.value=''});

render();
